def enable_open_waiting_rooms(apps, schema_editor):
    alias = schema_editor.connection.alias
    lessons = apps.get_model('live_lessons', 'LiveLesson').objects.using(alias).filter(
        audience='open', status__in=('scheduled', 'live'),
    )
    lessons.update(waiting_room_enabled=True)
    # Сохраняем допуск тех, кто уже участвовал в чате до появления зала ожидания.
    # У завершённых старых уроков не меняем исторические правила доступа.
    participants = apps.get_model('live_lessons', 'LiveLessonParticipant').objects.using(alias)
    messages = apps.get_model('live_lessons', 'LiveLessonMessage').objects.using(alias).filter(
        lesson__in=lessons,
    ).select_related('author').order_by('pk')
    for message in messages.iterator(chunk_size=200):
        if message.author_id:
            identity = f'course-user-{message.author_id}'
            name = (' '.join((message.author.first_name, message.author.last_name)).strip() or message.author.username)[:160]
        elif message.guest_id:
            identity = f'lesson-guest-{message.guest_id.hex}'
            name = message.guest_name
        else:
            continue
        participants.get_or_create(lesson_id=message.lesson_id, identity=identity,
                                   defaults={'name': name, 'admission': 'admitted'})


